args.script:
const active = game.modules.contents.filter(m => m.active).map(m => m.id).sort();
const cfg = game.settings.get("core", "moduleConfiguration");
const wanted = Object.keys(cfg).filter(k => cfg[k]).sort();
return {
  world: game.world.id,
  activeCount: active.length,
  active,
  wantedButNotActive: wanted.filter(id => !active.includes(id)),
  activeButNotWanted: active.filter(id => !wanted.includes(id)),
  scenePacks: game.packs.filter(p => p.documentName === "Scene").map(p => `${p.collection} (${p.index.size})`),
};

const out = {};
for (const p of game.packs.filter(p => p.documentName === "Scene" && p.collection !== "pentaryn-seafoot-maps.scenes")) {
  const docs = await p.getDocuments();
  out[p.collection] = docs.map(d => ({
    n: d.name,
    w: d.width, h: d.height,
    gs: d.grid?.size,
    walls: d.walls.size, lights: d.lights.size, tiles: d.tiles.size,
  }));
}
return out;

const root = await Folder.create({ name: "Suggestions", type: "Scene", color: "#c9a227", sorting: "m" });
const kids = [
  ["1 · Lower Tier — Harbor", "#3a7ca5"],
  ["2 · Middle Tier — Trade & Residential", "#7a9e4f"],
  ["3 · Upper Tier — Ridge", "#8e7cc3"],
  ["4 · The Keeps", "#a33a3a"],
  ["5 · The Ancient Tunnels", "#5c5c5c"],
  ["6 · Interiors — Inns, Shops & Halls", "#c07a2c"],
  ["7 · Outside the City", "#4f8f7a"],
];
const made = {};
for (const [name, color] of kids) {
  const f = await Folder.create({ name, type: "Scene", folder: root.id, color, sorting: "m" });
  made[name] = f.id;
}
return { root: root.id, made };

const pack = game.packs.get("pentaryn-seafoot-maps.scenes");
const folder = "AEayIJwYDR0VnOZ6";
const names = [
  "City of Saltspray",
  "Port of Inglesford", "Port of Inglesford Upper",
  "Port Riverfall",
  "Workshop Docks", "Workshop Docks Battle",
  "Fisher’s Market",
  "Town of Seacliff",
  "Gatehouse to the Seven Seas", "Gatehouse to the Seven Seas Upper",
  "Pirate's Secret Cove",
  "Ruined Workshop Docks",
];
const done = [], missing = [];
for (const n of names) {
  const e = pack.index.find(i => i.name === n);
  if (!e) { missing.push(n); continue; }
  const s = await game.scenes.importFromCompendium(pack, e._id, { folder, active: false, navigation: false });
  done.push(`${s.name} (${s.walls.size}w/${s.lights.size}l)`);
}
return { imported: done.length, done, missing };

const pack = game.packs.get("pentaryn-seafoot-maps.scenes");
const sets = {
  "WkmiuxxWQ5YFr9HK": [   // 2 · Middle Tier — Trade & Residential
    "City of Saltspray Middle Floors",
    "City of Turmburg Middle Floors",
    "Summer Marketplace", "Summer Marketplace Night",
    "Winter Marketplace",
    "Village Streets",
    "Streets", "Streets Night",
    "Underwood Market",
    "Fairfield Market",
    "Wintersreach Village",
    "Village Gatehouse",
  ],
  "Om0CrOO6bHJyy047": [   // 3 · Upper Tier — Ridge
    "City of Saltspray Top Floors",
    "City of Turmburg Top Floors",
    "Arken’s Ancient Library", "Arken’s Ancient Library Upper Ridge",
    "Clifftop Keep 1st floor", "Clifftop Keep Basement", "Clifftop Keep Roof",
    "Ruined Mountain Stronghold Upper Ridge",
    "Vault of Forbidden Knowledge",
  ],
};
const out = {}, missing = [];
for (const [folder, names] of Object.entries(sets)) {
  out[folder] = [];
  for (const n of names) {
    const e = pack.index.find(i => i.name === n);
    if (!e) { missing.push(n); continue; }
    const s = await game.scenes.importFromCompendium(pack, e._id, { folder, active: false, navigation: false });
    out[folder].push(s.name);
  }
}
return { counts: Object.fromEntries(Object.entries(out).map(([k,v]) => [k, v.length])), missing };

