args.script:
const P = {
  dmg: "dnd-dungeon-masters-guide.scenes",
  castle: "eledryll-maps-castle-life-bundle-1.eledryll-maps-castle-life-bundle-1",
  opera: "eledryll-spiders-tear-opera-house.eledryll-spiders-tear-opera-house",
  wiz1: "mad-endlesswiz.mad-endlesswiz-maps",
  wiz2: "mad-endlesswiz2.mad-endlesswiz2-maps",
};
const plan = [
  ["AEayIJwYDR0VnOZ6", P.dmg,    "Ship"],
  ["Om0CrOO6bHJyy047", P.opera,  "Spiders Tear Opera House - Day"],
  ["Om0CrOO6bHJyy047", P.wiz1,   "02. Library"],
  ["Om0CrOO6bHJyy047", P.wiz1,   "03. Observatory"],
  ["ma9gztNT5ozbdlTG", P.castle, "Windhorne Castle - Day"],
  ["ma9gztNT5ozbdlTG", P.castle, "Windhorne Castle - Night"],
  ["ma9gztNT5ozbdlTG", P.castle, "Brior Keep - Lit (Day - Spring)"],
  ["ma9gztNT5ozbdlTG", P.castle, "Throne Room - Dusk"],
  ["ma9gztNT5ozbdlTG", P.dmg,    "Keep"],
  ["ma9gztNT5ozbdlTG", P.dmg,    "Manor"],
  ["w5da6iv5V1GxyQDJ", P.castle, "Wine Cellar - Base"],
  ["w5da6iv5V1GxyQDJ", P.dmg,    "Barrow Crypt"],
  ["w5da6iv5V1GxyQDJ", P.dmg,    "Underdark Warren"],
  ["w5da6iv5V1GxyQDJ", P.dmg,    "Mine"],
  ["dqvSeg12qzuNxspu", P.dmg,    "Roadside Inn"],
  ["dqvSeg12qzuNxspu", P.wiz2,   "01. Alchemy Lab"],
  ["dqvSeg12qzuNxspu", P.wiz2,   "14. Vault"],
  ["HagoZLyJbpAwc0S1", P.dmg,    "Crossroads Village"],
  ["HagoZLyJbpAwc0S1", P.dmg,    "Farmstead"],
  ["HagoZLyJbpAwc0S1", P.dmg,    "Caravan Encampment"],
];
const done = [], missing = [];
for (const [folder, packId, name] of plan) {
  const pack = game.packs.get(packId);
  const e = pack?.index.find(i => i.name === name);
  if (!e) { missing.push(`${packId} :: ${name}`); continue; }
  const s = await game.scenes.importFromCompendium(pack, e._id, { folder, active: false, navigation: false });
  done.push(`${s.name} (${s.walls.size}w)`);
}
return { imported: done.length, done, missing, totalScenes: game.scenes.size };

const root = game.folders.find(f => f.name === "Suggestions" && f.type === "Scene");
const kids = game.folders.filter(f => f.folder?.id === root.id);
const inSug = new Set();
const counts = {};
for (const k of kids) {
  const s = game.scenes.filter(sc => sc.folder?.id === k.id);
  counts[k.name] = s.length;
  s.forEach(sc => inSug.add(sc.id));
}
return {
  counts,
  totalInSuggestions: inSug.size,
  totalScenes: game.scenes.size,
  outside: game.scenes.filter(s => !inSug.has(s.id)).map(s => ({ name: s.name, folder: s.folder?.name ?? null, active: s.active })),
  noWalls: game.scenes.filter(s => inSug.has(s.id) && s.walls.size === 0).map(s => s.name),
};

const je = game.journal.getName("Ardenford — Map Candidates");
const missing = je.pages.contents.filter(p => p.text.content?.includes("MISSING")).map(p => p.name);
return {
  world: game.world.id,
  missingRefs: missing,
  scenes: game.scenes.size,
  modulesActive: game.modules.filter(m => m.active).length,
  sceneFolders: game.folders.filter(f => f.type === "Scene").map(f => f.name),
  journalFolders: game.folders.filter(f => f.type === "JournalEntry").map(f => f.name),
};

const folders = game.folders.filter(f => f.type === "Compendium").map(f => ({ id: f.id, name: f.name, parent: f.folder?.id ?? null }));
const cfg = game.settings.get("core", "compendiumConfiguration");
return { folders, unfiled: game.packs.filter(p => !p.folder).map(p => p.collection), cfgKeys: Object.keys(cfg).length };

const cfg = foundry.utils.deepClone(game.settings.get("core", "compendiumConfiguration"));
cfg["pentaryn-seafoot-maps.scenes"] = { ...(cfg["pentaryn-seafoot-maps.scenes"] ?? {}), locked: false, folder: null };
await game.settings.set("core", "compendiumConfiguration", cfg);
return { seafoot: game.packs.get("pentaryn-seafoot-maps.scenes").locked };

const root = game.folders.find(f => f.name === "Suggestions" && f.type === "Scene");
const kids = game.folders.filter(f => f.folder?.id === root.id).sort((a,b) => a.name.localeCompare(b.name));
const sug = [];
const rows = kids.map(k => {
  const s = game.scenes.filter(x => x.folder?.id === k.id);
  s.forEach(x => sug.push(x));
  return { folder: k.name, scenes: s.length, minWalls: Math.min(...s.map(x => x.walls.size)) };
});
return {
  world: `${game.world.id} / ${game.world.title}`,
  modulesActive: game.modules.filter(m => m.active).length,
  lockRotation: game.settings.get("core", "prototypeTokenOverrides")?.npc?.lockRotation,
  rows,
  totalCandidates: sug.length,
  allWalled: sug.every(s => s.walls.size > 0),
  totalWalls: sug.reduce((n, s) => n + s.walls.size, 0),
  inNavBar: game.scenes.filter(s => s.navigation).map(s => s.name),
  activeScene: game.scenes.active?.name,
  journal: game.journal.getName("Ardenford — Map Candidates")?.pages.size + " pages",
};

const spec = [
  { name: "Jack", color: "#28cc71", avatar: "assets/tokens/custom/jack-token.webp" },
  { name: "Sean", color: "#287bcc", avatar: "assets/tokens/custom/sean-token.webp" },
  { name: "Zac",  color: "#8a6fd4", avatar: "assets/tokens/custom/zac-token.webp"  },
];
const made = [];
for (const s of spec) {
  if (game.users.getName(s.name)) { made.push(`${s.name}: already exists, skipped`); continue; }
  const u = await User.create({
    name: s.name,
    role: CONST.USER_ROLES.TRUSTED,   // 2 — same as Space Journey's Kristine/Kyle/Joe
    password: "",
    color: s.color,
    avatar: s.avatar,
    character: null,
  });
  made.push({ name: u.name, id: u.id, role: u.role, hasPassword: !!u.password, avatar: u.avatar, color: u.color });
}
return {
  created: made,
  allUsers: game.users.map(u => `${u.name} (role ${u.role}${u.isGM ? ", GM" : ""})`),
  roleNames: Object.fromEntries(Object.entries(CONST.USER_ROLES).map(([k, v]) => [v, k])),
};

const rows = [];
for (const u of game.users) {
  let ok = null;
  if (u.avatar) { try { ok = (await fetch("/" + u.avatar, { method: "HEAD" })).status; } catch (e) { ok = String(e); } }
  rows.push({ name: u.name, role: u.role, color: u._source.color, avatar: u.avatar, avatarHTTP: ok, password: u._source.password === "" ? "(none)" : "SET" });
}
const subj = ["jack-token-025881", "sean-token-af5f34", "zac-token-0e4a53"];
const subjOk = {};
for (const s of subj) subjOk[s] = (await fetch(`/assets/tokens/custom/ring-subjects/${s}.webp`, { method: "HEAD" })).status;
return { rows, ringSubjects: subjOk };

return {
  world: game.world.id,
  title: game.world.title,
  users: game.users.map(u => `${u.name} (role ${u.role})`),
  actors: game.actors.size,
  scenes: game.scenes.size,
  sceneFolders: game.folders.filter(f => f.type === "Scene").map(f => f.name),
  journalFolders: game.folders.filter(f => f.type === "JournalEntry").map(f => f.name),
  connectedUsers: game.users.filter(u => u.active).map(u => u.name),
};

const before = foundry.utils.deepClone(game.settings.get("core", "folderState") ?? {});
const state = game.settings.get("core", "folderState") ?? {};
const wanted = game.folders.filter(f => (f.type === "Scene" || f.type === "JournalEntry") && (f.name === "Suggestions" || f.name.match(/^[1-7] · /)));
for (const f of wanted) state[f.id] = true;
await game.settings.set("core", "folderState", state);
ui.scenes.render(true);
ui.journal.render(true);
return {
  expanded: wanted.map(f => `${f.type}: ${f.name}`),
  priorState: Object.keys(before).length,
  sceneTree: game.folders.filter(f => f.type === "Scene" && !f.folder).map(f => ({
    root: f.name,
    children: game.folders.filter(c => c.folder?.id === f.id).map(c => `${c.name} (${game.scenes.filter(s => s.folder?.id === c.id).length})`),
  })),
};

const out = {};
out.userFlags = game.user.flags?.core ? Object.keys(game.user.flags.core) : null;
out.expandedFlag = game.user.getFlag("core", "expandedFolders") ?? null;
out.settingsKeys = [...game.settings.settings.keys()].filter(k => /folder|expand|sidebar/i.test(k));
out.scenesDirProps = Object.getOwnPropertyNames(ui.scenes).filter(p => /expand|folder|collaps/i.test(p));
out.folderSample = (() => { const f = game.folders.find(x => x.name === "Suggestions" && x.type === "Scene"); return { id: f.id, expanded: f.expanded, keys: Object.keys(f).slice(0, 20) }; })();
return out;

const store = game.folders._expanded;
const ids = game.folders
  .filter(f => (f.type === "Scene" || f.type === "JournalEntry") && (f.name === "Suggestions" || /^[1-7] · /.test(f.name)))
  .map(f => f.id);
let method = null;
if (store && typeof store === "object") {
  for (const id of ids) store[id] = true;
  method = "game.folders._expanded";
}
ui.scenes.render(true);
ui.journal.render(true);
const f = game.folders.find(x => x.name === "Suggestions" && x.type === "Scene");
return {
  method, expandedNow: f.expanded, count: ids.length,
  tree: game.folders.filter(x => x.type === "Scene" && !x.folder).map(r => ({
    root: r.name,
    children: game.folders.filter(c => c.folder?.id === r.id).map(c => `${c.name} → ${game.scenes.filter(s => s.folder?.id === c.id).length} scenes`),
  })),
};

const spec = [
  { user: "Jack", art: "assets/tokens/custom/jack-token.webp", subj: "assets/tokens/custom/ring-subjects/jack-token-025881.webp" },
  { user: "Sean", art: "assets/tokens/custom/sean-token.webp", subj: "assets/tokens/custom/ring-subjects/sean-token-af5f34.webp" },
  { user: "Zac",  art: "assets/tokens/custom/zac-token.webp",  subj: "assets/tokens/custom/ring-subjects/zac-token-0e4a53.webp"  },
];
const out = [];
for (const s of spec) {
  const u = game.users.getName(s.user);
  if (!u) { out.push(`${s.user}: no such user`); continue; }
  if (game.actors.getName(s.user)) { out.push(`${s.user}: actor already exists, skipped`); continue; }
  const actor = await Actor.create({
    name: s.user,
    type: "character",
    img: s.art,
    ownership: { default: CONST.DOCUMENT_OWNERSHIP_LEVELS.NONE, [u.id]: CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER },
    prototypeToken: {
      name: s.user,
      texture: { src: s.art, fit: "contain", anchorX: 0.5, anchorY: 0.5, alphaThreshold: 0.75, scaleX: 1, scaleY: 1, tint: "#ffffff" },
      ring: { enabled: true, effects: 1, colors: { ring: "#ffcc4d", background: "#3a2d16" }, subject: { scale: 1, texture: s.subj } },
      width: 1, height: 1, lockRotation: true, displayName: 30, disposition: 1, actorLink: true,
      sight: { enabled: true, visionMode: "basic", range: 0, angle: 360, attenuation: 0.1, brightness: 0, saturation: 0, contrast: 0 },
    },
  });
  await u.update({ character: actor.id });
  out.push({ actor: actor.name, id: actor.id, owner: s.user, ring: actor.prototypeToken.ring.subject.texture, linked: actor.prototypeToken.actorLink });
}
return { out, actors: game.actors.map(a => `${a.name} (${a.type})`), assigned: game.users.map(u => `${u.name} → ${u.character?.name ?? "—"}`) };

const res = await fetch("/worlds/ardenford/_import-tavern.json");
if (!res.ok) return { error: `staged file ${res.status}` };
const data = await res.json();

// Folders
const sceneFolder = await Folder.create({ name: "The Wayward Compass", type: "Scene", color: "#8a5a2b", sorting: "m" });
const actorFolder = await Folder.create({ name: "The Wayward Compass", type: "Actor", color: "#8a5a2b", sorting: "m" });

// Actors first — tokens reference them by id.
const actorData = data.actors.map(a => ({ ...a, folder: actorFolder.id }));
const madeActors = await Actor.createDocuments(actorData, { keepId: true });

// Scenes, renamed for the location.
const rename = {
  "1. Dragonsfall Tavern Night": "1. The Wayward Compass — Common Room",
  "2. Dragonsfall Tavern 2nd Floor Night": "2. The Wayward Compass — Guest Rooms",
  "3. Dragonsfall Tavern Roof Night": "3. The Wayward Compass — Roof",
};
const sceneData = data.scenes.map(s => ({
  ...s,
  name: rename[s.name] ?? s.name,
  folder: sceneFolder.id,
  active: false,
  navigation: false,
  thumb: s.thumb?.replace("worlds/space-journey/", "worlds/ardenford/") ?? s.thumb,
}));
const madeScenes = await Scene.createDocuments(sceneData, { keepId: true });

return {
  actors: madeActors.length,
  scenes: madeScenes.map(s => ({
    name: s.name, id: s.id,
    walls: s.walls.size, lights: s.lights.size, sounds: s.sounds.size,
    tokens: s.tokens.size, regions: s.regions.size,
    brokenTokens: s.tokens.filter(t => t.actorId && !game.actors.get(t.actorId)).length,
  })),
};

const out = [];
for (const s of game.scenes.filter(x => x.folder?.name === "The Wayward Compass")) {
  for (const r of s.regions) {
    for (const b of r.behaviors) {
      const dests = (b.system?.destinations ?? []).map(uuid => {
        const doc = fromUuidSync(uuid);
        return { uuid, resolves: !!doc, to: doc ? `${doc.parent?.name} → ${doc.name}` : null };
      });
      out.push({ scene: s.name, region: r.name, behavior: b.type, dests });
    }
  }
}
return { links: out, allResolve: out.every(l => l.dests.every(d => d.resolves)) };

script.head:
const T = "assets/tokens/tokens-01/";
const R = "assets/tokens/custom/ring-subjects/";
const V = "assets/tokens/custom/g

args.script:
const harl = game.actors.getName("Harl Wetherby");
const thorgrim = game.actors.getName("Thorgrim Ledger-Scar");
const report = [];
for (const scene of game.scenes.filter(s => s.folder?.name === "The Wayward Compass")) {
  const his = scene.tokens.filter(t => t.actorId === harl?.id);
  if (!his.length) continue;
  // Put Thorgrim on the first one's square, drop the rest.
  const spot = his[0];
  const proto = thorgrim.prototypeToken.toObject();
  await scene.createEmbeddedDocuments("Token", [{
    ...proto, actorId: thorgrim.id, x: spot.x, y: spot.y, elevation: spot.elevation, sort: spot.sort,
  }]);
  await scene.deleteEmbeddedDocuments("Token", his.map(t => t.id));
  report.push(`${scene.name}: Thorgrim placed at (${spot.x}, ${spot.y}); removed ${his.length} Harl Wetherby token(s)`);
}
// tidy the folder the NPC tool created
const mcpFolder = game.folders.find(f => f.type === "Actor" && f.name === "Foundry MCP Creatures");
let folderNote = null;
if (mcpFolder) {
  const left = game.actors.filter(a => a.folder?.id === mcpFolder.id).length;
  if (!left) { await mcpFolder.delete(); folderNote = "deleted empty 'Foundry MCP Creatures' folder"; }
  else folderNote = `'Foundry MCP Creatures' kept — ${left} actor(s) still in it`;
}
return {
  report, folderNote,
  commonRoomTokens: game.scenes.getName("1. The Wayward Compass — Common Room").tokens.size,
  actorFolders: game.folders.filter(f => f.type === "Actor").map(f => `${f.name} (${game.actors.filter(a => a.folder?.id === f.id).length})`),
};

const bad = [];
for (const a of game.actors) {
  for (const [label, p] of [["img", a.img], ["texture", a.prototypeToken.texture.src], ["subject", a.prototypeToken.ring.subject?.texture]]) {
    if (!p || p.startsWith("icons/")) continue;
    const r = await fetch("/" + p, { method: "HEAD" });
    if (r.status !== 200) bad.push(`${a.name} ${label}: ${p} → ${r.status}`);
  }
}
const tier = a => a.prototypeToken.ring.enabled ? a.prototypeToken.ring.colors.ring : "no ring (crowd)";
return {
  world: game.world.id,
  totals: { actors: game.actors.size, scenes: game.scenes.size, users: game.users.size },
  actorFolders: game.folders.filter(f => f.type === "Actor").map(f => `${f.name}: ${game.actors.filter(a => a.folder?.id === f.id).length}`),
  ringTiers: {
    PCs: game.actors.filter(a => a.type === "character").map(a => `${a.name} ${tier(a)}`),
    townsfolkSample: game.actors.filter(a => a.folder?.name === "Ardenford — Townsfolk").slice(0, 3).map(a => `${a.name} ${tier(a)}`),
    extrasSample: game.actors.filter(a => a.folder?.name === "Ardenford — Extras (crowd)").slice(0, 2).map(a => `${a.name} ${tier(a)} src=${a.prototypeToken.texture.src.includes("ring-subjects") ? "⅔ subject ✓" : "RAW ART ✗"}`),
  },
  brokenPaths: bad,
  harlLeft: game.scenes.filter(s => s.folder?.name === "The Wayward Compass").reduce((n, s) => n + s.tokens.filter(t => t.actor?.name === "Harl Wetherby").length, 0),
  thorgrimTokens: game.scenes.filter(s => s.tokens.some(t => t.actor?.name === "Thorgrim Ledger-Scar")).map(s => s.name),
};

const fixes = {
  "assets/tokens/tokens-01/humans-male/veteran-in-plate-armor.png": "assets/tokens/tokens-01/humans/humans-male/veteran-in-plate-armor.png",
  "assets/tokens/tokens-01/humans-male/grey-armored-fighter.png":   "assets/tokens/tokens-01/humans/humans-male/grey-armored-fighter.png",
  "assets/tokens/tokens-01/humans-male/human-warrior-stern.png":    "assets/tokens/tokens-01/humans/humans-male/human-warrior-stern.png",
  "assets/tokens/tokens-01/humans-female/determined-captain.png":   "assets/tokens/tokens-01/humans/humans-female/determined-captain.png",
};
// confirm the corrected paths actually serve before writing
const checked = {};
for (const [from, to] of Object.entries(fixes)) checked[to] = (await fetch("/" + to, { method: "HEAD" })).status;
if (Object.values(checked).some(s => s !== 200)) return { aborted: true, checked };

const done = [];
for (const a of game.actors) {
  const upd = {};
  if (fixes[a.img]) upd.img = fixes[a.img];
  if (fixes[a.prototypeToken.texture.src]) upd["prototypeToken.texture.src"] = fixes[a.prototypeToken.texture.src];
  if (Object.keys(upd).length) { await a.update(upd); done.push(a.name); }
}
// placed tokens don't inherit prototype changes
let tokensFixed = 0;
